package top.aameow.management.service;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.transaction.annotation.Transactional;import top.aameow.management.mapper.ProjectResourcesMapper;import top.aameow.common.exception.ServiceException;import top.aameow.common.utils.SecurityUtils;
@Service public class ProjectResourcesService {
 @Autowired private ProjectResourcesMapper mapper;@Autowired private WorkProjectService projects;@Autowired private BusinessFiles files;
 public ProjectResourcesMapper data(){return mapper;}public Map<String,Object> project(Long id){return projects.get(id);}
 public void maintenance(Long id){if(!"WB".equals(project(id).get("projectType")))throw new ServiceException("资料面板仅用于维护保养项目");}
 @Transactional(rollbackFor=Exception.class) public void document(Long id,Map<String,Object> v){project(id);String name=WorkProjectService.text(v,"name"),kind=WorkProjectService.text(v,"kind");if(name.isEmpty()||name.length()>255||!List.of("report","report_attachment","other").contains(kind))throw new ServiceException("请填写文件名称及有效分类");String urls=WorkProjectService.text(v,"files");if(urls.length()>20000)throw new ServiceException("文件数量超出限制");v.put("name",name);v.put("projectId",id);v.put("actor",SecurityUtils.getUsername());if((v.get("id")==null?mapper.add(v):mapper.edit(v))!=1)throw new ServiceException("文件记录不存在或不属于此项目");files.save("project_document",WorkProjectService.number(v.get("id")),urls);}
 @Transactional(rollbackFor=Exception.class) public void remove(Long p,Long id){project(p);if(mapper.remove(p,id)!=1)throw new ServiceException("文件不属于此项目或已删除");files.save("project_document",id,"");}
 @Transactional(rollbackFor=Exception.class) public void material(Long id,Map<String,Object> v){maintenance(id);Long mid=WorkProjectService.number(v.get("materialId")),cid=WorkProjectService.number(v.get("cardId"));if(mid!=null&&mapper.attachment(mid)==null)throw new ServiceException("附带资料不存在");if(cid!=null&&mapper.card(cid)==null)throw new ServiceException("维保卡不存在");v.put("projectId",id);v.put("materialId",mid);v.put("cardId",cid);v.put("version",WorkProjectService.number(v.get("version")));mapper.ensureMaterial(id);if(mapper.material(v)!=1)throw new ServiceException("资料已被修改，请刷新后重试");}
}
